const CALENDLY_BASE_URL = "https://api.calendly.com";

if (!process.env.CALENDLY_PERSONAL_ACCESS_TOKEN) {
  throw new Error("CALENDLY_PERSONAL_ACCESS_TOKEN is missing from .env.local");
}

export async function calendlyRequest<T>(
  method: "GET" | "POST" | "DELETE",
  endpoint: string,
  params?: Record<string, string>,
): Promise<T> {
  const url = new URL(`${CALENDLY_BASE_URL}${endpoint}`);
  if (method === "GET" && params) {
    for (const [key, value] of Object.entries(params)) {
      url.searchParams.set(key, value);
    }
  }

  const response = await fetch(url.toString(), {
    method,
    headers: {
      Authorization: `Bearer ${process.env.CALENDLY_PERSONAL_ACCESS_TOKEN}`,
      "Content-Type": "application/json",
    },
    body: method !== "GET" && params ? JSON.stringify(params) : undefined,
  });

  if (!response.ok) {
    const error = await response.json().catch(() => ({}));
    throw new Error(
      (error as { message?: string }).message ??
        `Calendly API error: ${response.status}`,
    );
  }

  return response.json() as Promise<T>;
}

