"use server";

import { calendlyRequest } from "./client";

export interface CalendlyUser {
  uri: string;
  name: string;
  email: string;
  slug: string;
  scheduling_url: string;
  timezone: string;
}

export interface CalendlyEventType {
  uri: string;
  name: string;
  active: boolean;
  slug: string;
  scheduling_url: string;
  duration: number;
  kind: "solo" | "group";
  color: string;
  description_plain: string | null;
}

export interface CalendlyScheduledEvent {
  uri: string;
  name: string;
  status: "active" | "canceled";
  start_time: string;
  end_time: string;
  event_type: string;
  location: { type: string; location?: string } | null;
  invitees_counter: { total: number; active: number; limit: number };
  created_at: string;
  updated_at: string;
}

export interface CalendlyInvitee {
  uri: string;
  email: string;
  name: string;
  status: "active" | "canceled";
  timezone: string;
  created_at: string;
  updated_at: string;
}

export interface ListOptions {
  count?: number;
  status?: "active" | "canceled";
  sort?: string;
}

// The current user's URI is required as a query param for listing event types
// and scheduled events. This helper is called internally by the other actions.
export async function getCurrentUser(): Promise<CalendlyUser> {
  const { resource } = await calendlyRequest<{ resource: CalendlyUser }>(
    "GET",
    "/users/me",
  );
  return resource;
}

export async function listEventTypes(
  options?: { count?: number; active?: boolean },
): Promise<CalendlyEventType[]> {
  const user = await getCurrentUser();
  const params: Record<string, string> = { user: user.uri };
  if (options?.count !== undefined) params.count = String(options.count);
  if (options?.active !== undefined) params.active = String(options.active);
  const { collection } = await calendlyRequest<{
    collection: CalendlyEventType[];
  }>("GET", "/event_types", params);
  return collection;
}

export async function listScheduledEvents(
  options?: ListOptions,
): Promise<CalendlyScheduledEvent[]> {
  const user = await getCurrentUser();
  const params: Record<string, string> = { user: user.uri };
  if (options?.count !== undefined) params.count = String(options.count);
  if (options?.status) params.status = options.status;
  if (options?.sort) params.sort = options.sort;
  const { collection } = await calendlyRequest<{
    collection: CalendlyScheduledEvent[];
  }>("GET", "/scheduled_events", params);
  return collection;
}

export async function getScheduledEvent(
  uuid: string,
): Promise<CalendlyScheduledEvent> {
  const { resource } = await calendlyRequest<{
    resource: CalendlyScheduledEvent;
  }>("GET", `/scheduled_events/${uuid}`);
  return resource;
}

export async function listInvitees(
  eventUuid: string,
  options?: ListOptions,
): Promise<CalendlyInvitee[]> {
  const params: Record<string, string> = {};
  if (options?.count !== undefined) params.count = String(options.count);
  if (options?.status) params.status = options.status;
  const { collection } = await calendlyRequest<{
    collection: CalendlyInvitee[];
  }>("GET", `/scheduled_events/${eventUuid}/invitees`, params);
  return collection;
}

