import crypto from "crypto";

export interface CalendlyInviteePayload {
  uri: string;
  name: string;
  email: string;
  status: string;
  timezone: string;
  event: string;
  event_type: string;
}

export interface CalendlyWebhookEvent {
  event: string;
  created_at: string;
  created_by: string;
  payload: CalendlyInviteePayload & {
    routing_form_submission?: Record<string, unknown>;
  };
}

// Reject webhooks older than 5 minutes — guards against replay attacks.
const SIGNATURE_TOLERANCE_MS = 5 * 60 * 1000;

/**
 * Verifies the Calendly webhook signature.
 *
 * Calendly header format: `t=<unix_timestamp>,v1=<hmac_sha256>`
 * Signed payload:         `<timestamp>.<raw_body>`
 *
 * The 5-minute timestamp tolerance prevents replay attacks
 * (an attacker re-sending a valid old request).
 */
export function verifyWebhookSignature(
  body: string,
  signatureHeader: string,
  signingKey: string,
): boolean {
  const parts: Record<string, string> = {};
  for (const part of signatureHeader.split(",")) {
    const [key, ...rest] = part.split("=");
    if (key) parts[key] = rest.join("=");
  }

  const timestamp = parts["t"];
  const signature = parts["v1"];
  if (!timestamp || !signature) return false;

  const eventTimeMs = parseInt(timestamp, 10) * 1000;
  if (Math.abs(Date.now() - eventTimeMs) > SIGNATURE_TOLERANCE_MS) return false;

  const expected = crypto
    .createHmac("sha256", signingKey)
    .update(`${timestamp}.${body}`)
    .digest("hex");

  const a = Buffer.from(expected, "utf8");
  const b = Buffer.from(signature, "utf8");
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

export async function handleCalendlyEvent(
  event: CalendlyWebhookEvent,
): Promise<void> {
  switch (event.event) {
    case "invitee.created": {
      console.log(
        `[calendly] New booking: ${event.payload.name} <${event.payload.email}>`,
      );
      // TODO: Add your logic — send confirmation email, create DB record, notify team
      break;
    }
    case "invitee.canceled": {
      console.log(
        `[calendly] Canceled: ${event.payload.name} <${event.payload.email}>`,
      );
      // TODO: Add your logic — send cancellation email, free up resources
      break;
    }
    case "routing_form_submission.created": {
      console.log("[calendly] Routing form submission received");
      // TODO: Add your routing logic here
      break;
    }
    default:
      console.log(`[calendly] Unhandled event: ${event.event}`);
  }
}

