import { headers } from "next/headers";
import {
  handleCalendlyEvent,
  verifyWebhookSignature,
} from "@/infra/calendly/webhooks";

export async function POST(req: Request) {
  const body = await req.text();
  const headersList = await headers();
  const signature = headersList.get("Calendly-Webhook-Signature");

  if (!signature) {
    return new Response("Bad request", { status: 400 });
  }

  if (!process.env.CALENDLY_WEBHOOK_SIGNING_KEY) {
    console.error("[calendly webhook] CALENDLY_WEBHOOK_SIGNING_KEY is not set");
    return new Response("Server misconfiguration", { status: 500 });
  }

  if (
    !verifyWebhookSignature(
      body,
      signature,
      process.env.CALENDLY_WEBHOOK_SIGNING_KEY,
    )
  ) {
    console.error("[calendly webhook] Invalid signature");
    return new Response("Unauthorized", { status: 401 });
  }

  // Parse FIRST — malformed JSON is a permanent error (400, no retry).
  let event;
  try {
    event = JSON.parse(body);
  } catch (err: unknown) {
    console.error("[calendly webhook] Malformed JSON", err);
    return new Response("Bad request", { status: 400 });
  }

  // Handler errors are 500 so Calendly retries — distinct from 4xx above.
  try {
    await handleCalendlyEvent(event);
    return new Response("OK", { status: 200 });
  } catch (err: unknown) {
    console.error("[calendly webhook] Handler error", err);
    return new Response("Internal error", { status: 500 });
  }
}
